from collections import deque

def graph_fill(arr, mask_color, source_colors):
 R,C=arr.shape
 mask=arr==mask_color
 seeds={}
 for r,c in np.argwhere(mask):
  vals=[]
  for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
   rr,cc=r+dr,c+dc
   if 0<=rr<R and 0<=cc<C and arr[rr,cc] in source_colors: vals.append(int(arr[rr,cc]))
  if vals:
   # dominant immediate values, tie multi
   seeds[(r,c)]=set(vals)
 dist={}; labels={}; q=deque()
 for p,ls in seeds.items():
  dist[p]=0; labels[p]=set(ls); q.append(p)
 while q:
  p=q.popleft(); r,c=p
  for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
   pp=(r+dr,c+dc)
   if 0<=pp[0]<R and 0<=pp[1]<C and mask[pp]:
    nd=dist[p]+1
    if pp not in dist:
     dist[pp]=nd; labels[pp]=set(labels[p]); q.append(pp)
    elif nd==dist[pp]: labels[pp]|=labels[p]
 out=arr.copy()
 for p,ls in labels.items():
  if len(ls)==1:out[p]=next(iter(ls))
 return out,dist,labels,seeds
